reactive_counter.code:
import { cairn, state, div, h1, button, mount } from '@eldrex/cairnjs';

const count = state(0);
const App = () => div({ style: { padding: '2rem', textAlign: 'center' } },
    h1(() => `Count: ${count.value}`),
    button('Increment (+1)', {
        onclick: () => count.value++,
        style: { padding: '0.5rem 1rem', background: '#0284c7', color: '#fff', border: 'none', borderRadius: '0.5rem', cursor: 'pointer' }
    })
);

mount('#app', App());

pure_html_template.code:
import { cairn } from '@eldrex/cairnjs';
const { state, html, mount } = cairn;

const name = state('');
const App = () => html`
  <div style="padding: 2rem;">
    <input :bind=${name} placeholder="Enter name..." />
    <p>Hello, ${() => name.value || 'Friend'}!</p>
  </div>
`;

mount('#app', App());

