import { spring } from '@eldrex/cairnjs';

spring({
    from: 0,
    to: 100,
    stiffness: 260,
    damping: 14,
    onUpdate: (x) => { element.style.transform = `translateX(${x}px)`; }
});

framework_bridge_react.code:
import React from 'react';
import { cairnToReact, div, button } from '@eldrex/cairnjs';

const CairnWidget = (props) => div(
    button(props.label || 'Click me', { onclick: props.onClick })
);

export const ReactWidget = cairnToReact(CairnWidget);

custom_error_diagnostics.code:
import { errors, cairnError } from '@eldrex/cairnjs';

errors.customize('missing_config', (ctx) => ({
    summary: `Missing mandatory config key: ${ctx.key}`,
    location: `ConfigLoader(${ctx.file})`,
    fix: `Provide ${ctx.key} in your options object.`
}));

cairnError('missing_config', { key: 'apiUrl', file: 'app.config.js' });
